package com.contextgraph.controller; import com.contextgraph.dto.AuthDtos; import com.contextgraph.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController{final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register")public AuthDtos.AuthResponse register(@Valid @RequestBody AuthDtos.RegisterRequest r){return auth.register(r);}@PostMapping("/login")public AuthDtos.AuthResponse login(@Valid @RequestBody AuthDtos.LoginRequest r){return auth.login(r);}}